/**
 * Responsibility: assemble requested live context layers for one turn.
 * Scope: self-knowledge, skills, workspace knowledge, recent artifacts, and host facts.
 * Rules: semantic classification selects layers; this module only resolves and composes them.
 */
import { getSelfKnowledgeContext } from './self-knowledge.ts'
import { listSkills } from './skills.ts'
import { getPersonalKnowledgeBase, resolveKnowledgeContext } from './knowledge/index.ts'
import { formatSystemInfo, getSystemInfo } from './system-info.ts'

export type DynamicContextLayer =
  | 'self_knowledge'
  | 'skills_catalog'
  | 'workspace_docs'
  | 'recent_artifacts'
  | 'system_info'

export async function resolveDynamicContext(
  layers: DynamicContextLayer[],
  query: string,
  cwd?: string,
): Promise<string> {
  if (layers.length === 0) return ''

  const resolved = await Promise.all(
    [...new Set(layers)].map(async layer => {
      switch (layer) {
        case 'self_knowledge':
          return `System Self-Knowledge:\n${getSelfKnowledgeContext()}`

        case 'skills_catalog': {
          const skills = await listSkills()
          if (skills.length === 0) {
            return 'Skills Catalog (managed by @dharmax/skill-manager):\nNo skills are currently installed.'
          }
          const list = skills
            .map(skill => `• ${skill.name} (${skill.id}): ${skill.description}`)
            .join('\n')
          return `Skills Catalog (managed by @dharmax/skill-manager, ${skills.length} active):\n${list}`
        }

        case 'workspace_docs':
          return cwd ? resolveKnowledgeContext(query, 'workspace_local', cwd) : ''

        case 'recent_artifacts': {
          const docs = await getPersonalKnowledgeBase().getLatestDocuments('artifacts', 5)
          if (docs.length === 0) {
            return 'Recent Generated Artifacts: None currently recorded in Semantika memory.'
          }
          const list = docs
            .map(doc => `• [${doc.data.type || 'artifact'}] ${doc.data.path} (Prompt: "${doc.data.prompt || ''}")`)
            .join('\n')
          return `Recent Generated Artifacts (from Semantika memory):\n${list}`
        }

        case 'system_info':
          return formatSystemInfo(getSystemInfo({ purpose: 'context grounding' })).trim()
      }
    }),
  )

  return resolved.filter(Boolean).join('\n\n')
}

