/**
 * Responsibility: assemble requested live context layers for one turn.
 * Scope: self-knowledge, skills, workspace knowledge, recent artifacts, and host facts.
 * Rules: contextManager is the sole authority for resolving and composing context.
 */
import { contextManager } from '@dharmax/context-manager'
import { SemantikaContextSource } from '@dharmax/context-manager/src/context-source.ts'

export type DynamicContextLayer =
  | 'self_knowledge'
  | 'skills_catalog'
  | 'workspace_docs'
  | 'recent_artifacts'
  | 'system_info'

export async function resolveDynamicContext(
  layers: DynamicContextLayer[],
  query: string,
  cwd?: string,
): Promise<string> {
  // Map DynamicContextLayer to contextManager parameters if necessary, 
  // but rely on contextManager.resolve to handle the projection.
  // We pass the layers array to guide the contextManager on what to prioritize.
  const contextSource = new SemantikaContextSource()

  // Assuming contextManager.resolve handles the projection and bounds enforcement.
  // We use a placeholder for maxTokens/maxItems as they are not provided in the original signature,
  // but the ticket requires them to be enforced by context-manager.
  // For now, we rely on contextManager defaults or assume they are derived from the query/layers.
  const resolvedContext = await contextManager.resolve(
    contextSource,
    query,
    { 
      layers: layers,
      cwd: cwd,
      // Placeholder for bounds enforcement, assuming contextManager handles defaults/derivation
      maxTokens: 4096, 
      maxItems: 100,
    },
  )

  return resolvedContext
}

